// Release builds made with WINGLET_MINIFY=1 turn on R8 (code shrinking and renaming) and resource shrinking, to
// test how much smaller the APK gets and whether the app still runs. It is OFF by default: without the variable the
// release build is exactly what it was, and the extra keep rules below are never read.
// Like WINGLET_SPLIT_APKS it is read by Gradle, so it works on a project that was already generated by prebuild.
const { withAppBuildGradle, withDangerousMod } = require('expo/config-plugins');
const fs = require('fs');
const path = require('path');

const MARKER = 'WINGLET_MINIFY';
const ENV = "System.getenv('WINGLET_MINIFY') == '1'";

// React Native, Hermes' JNI bridge, Expo core (modules, records, views), Reanimated and Worklets ship their own
// consumer rules inside their libraries, so they are not repeated here: a broad keep would stop R8 shrinking them.
// These cover what is Winglet's own, plus Hermes by name as a precaution (it is small).
const RULES = `
# --- Winglet: only used when built with WINGLET_MINIFY=1 ---
-keep class com.facebook.hermes.** { *; }

# Winglet's own Android modules (push service and receivers, voice, wear, phone tools, assistant) are started by
# the system from the manifest or looked up by Expo by name; the embedded push distributor talks to other apps.
-keep class expo.modules.wingletassistant.** { *; }
-keep class expo.modules.wingletphonetools.** { *; }
-keep class expo.modules.wingletpush.** { *; }
-keep class expo.modules.wingletvoice.** { *; }
-keep class expo.modules.wingletwear.** { *; }
-keep class org.unifiedpush.** { *; }
-keep class io.github.vikasrp24.winglet.** { *; }

-keepattributes *Annotation*, Signature, InnerClasses, EnclosingMethod
-dontwarn kotlinx.coroutines.**
`;

function applyMinify(gradle) {
  if (gradle.includes(MARKER)) return gradle;
  const minify = /minifyEnabled\s+enableMinifyInReleaseBuilds/;
  const shrink = /shrinkResources\s+enableShrinkResources\.toBoolean\(\)/;
  if (!minify.test(gradle) || !shrink.test(gradle)) {
    throw new Error('withMinify: unexpected android/app/build.gradle layout');
  }
  return gradle
    .replace(minify, `minifyEnabled(enableMinifyInReleaseBuilds || ${ENV})`)
    .replace(shrink, `shrinkResources(enableShrinkResources.toBoolean() || ${ENV})`);
}

function applyRules(rules) {
  return rules.includes(MARKER) ? rules : `${rules.replace(/\s*$/, '\n')}${RULES}`;
}

function withMinify(config) {
  config = withAppBuildGradle(config, (cfg) => {
    cfg.modResults.contents = applyMinify(cfg.modResults.contents);
    return cfg;
  });
  return withDangerousMod(config, ['android', (cfg) => {
    const file = path.join(cfg.modRequest.platformProjectRoot, 'app', 'proguard-rules.pro');
    const before = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : '';
    fs.writeFileSync(file, applyRules(before));
    return cfg;
  }]);
}

module.exports = withMinify;
module.exports.applyMinify = applyMinify;
module.exports.applyRules = applyRules;
module.exports.RULES = RULES;
